  | "NODE_UP"
  | "NODE_DOWN"
  | "ANOMALY_DETECTED"
  | "AGENT_ANALYZING"
  | "AGENT_STEP"
  | "FILTER_GENERATED"
  | "VERIFYING"
  | "VERIFY_FAILED"
  | "VERIFY_PASSED"
  | "OTA_DEPLOYING"
  | "DEPLOYED"
  | "FRAME_BLOCKED";

export interface NodeView {
  node_id: string;
  state: NodeState;
  last_seen: number;
  fw_version: string;
  label: string;
  blocked: number;
}

export interface Counters {
  active_nodes: number;
  threats_detected: number;
  filters_deployed: number;
  frames_blocked: number;
}

