1	// Pure reducer: folds WS messages into dashboard state. No React, no I/O -
2	// so it is unit-testable in isolation (see reducer.test.ts).
3	
4	import type { DashState, LiveEvent, NodeState, TimelineLine, WsMessage } from "./types";
5	
6	export const initialState: DashState = {
7	  nodes: {},
8	  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
9	  timeline: [],
10	  stage: "idle",
11	  activeNode: null,
12	  activeAttack: null,
13	  agent: { iterations: null, self_tpr: null, self_fpr: null },
14	  agentStatus: null,
15	  error: null,
16	  seq: 0,
17	};
18	
19	const PROGRESS_PREFIX = "⏳";
20	
21	const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
22	  ANOMALY_DETECTED: "trigger",
23	  AGENT_ANALYZING: "agent",
24	  VERIFYING: "verify",
25	  OTA_DEPLOYING: "ota",
26	  DEPLOYED: "done",
27	};
28	
29	function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
30	  const p = e.payload;
31	  const node = e.node_id ?? "system";
32	  switch (e.type) {
33	    case "NODE_UP":
34	      return { text: `${node} online`, tone: "info" };
35	    case "NODE_DOWN":
36	      return { text: `${node} went offline`, tone: "bad" };
37	    case "ANOMALY_DETECTED":
38	      return { text: `${node} anomaly: ${p.count ?? "?"} frames in window`, tone: "warn" };
39	    case "AGENT_ANALYZING":
40	      return { text: `${node} agent analyzing (attempt ${p.attempt ?? 1})`, tone: "info" };
41	    case "AGENT_STEP":
42	      return { text: `${node} sandbox: ${p.text ?? ""}`, tone: "info" };
43	    case "FILTER_GENERATED": {
44	      const iters = p.iterations ? ` (${p.iterations} sandbox iters)` : "";
45	      return { text: `${node} filter generated: ${p.attack_class ?? "?"}${iters}`, tone: "info" };
46	    }
47	    case "VERIFYING":
48	      return { text: `${node} verifying filter (replay test)`, tone: "info" };
49	    case "VERIFY_FAILED":
50	      return { text: `${node} verify FAILED ${p.tests ?? ""} (fpr=${p.fpr ?? "?"})`, tone: "bad" };
51	    case "VERIFY_PASSED":
52	      return { text: `${node} verify PASSED ${p.tests ?? ""}`, tone: "ok" };
53	    case "OTA_DEPLOYING":
54	      return { text: `${node} deploying filter OTA`, tone: "info" };
55	    case "DEPLOYED":
56	      return { text: `${node} PROTECTED: ${p.attack_class ?? "filter"} deployed`, tone: "ok" };
57	    case "FRAME_BLOCKED":
58	      return { text: `${node} blocked ${p.count ?? 1} attack frames`, tone: "ok" };
59	    case "LINK_SUBMITTED":
60	      return { text: `scanning link ${p.url ?? ""}`, tone: "info" };
61	    case "LINK_BROWSING":
62	      return { text: `browse-agent walking ${p.url ?? ""}`, tone: "info" };
63	    case "LINK_RESEARCHING":
64	      return { text: `research-agent checking reputation`, tone: "info" };
65	    case "LINK_VERDICT": {
66	      const bad = p.verdict === "malicious" || p.verdict === "suspicious";
67	      const brand = p.brand ? ` — impersonates ${p.brand}` : "";
68	      return {
69	        text: `link verdict: ${p.verdict ?? "?"} (${p.legit_score ?? "?"})${brand}`,
70	        tone: bad ? "bad" : "ok",
71	      };
72	    }
73	    default:
74	      return { text: e.type, tone: "info" };
75	  }
76	}
77	
78	function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
79	  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
80	  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
81	}
82	
83	export function reduce(state: DashState, msg: WsMessage): DashState {
84	  if (msg.type === "SNAPSHOT") {
85	    const nodes: DashState["nodes"] = {};
86	    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
87	    return { ...state, nodes, counters: msg.payload.counters };
88	  }
89	
90	  const e = msg;
91	  let nodes = state.nodes;
92	  const counters = { ...state.counters };
93	  let activeNode = state.activeNode;
94	  let activeAttack = state.activeAttack;
95	  let agent = state.agent;
96	  let agentStatus = state.agentStatus;
97	  let error = state.error;
98	  let appendLine = true;
99	
100	  switch (e.type) {
101	    case "NODE_UP":
102	      if (e.node_id && !nodes[e.node_id]) {
103	        nodes = {
104	          ...nodes,
105	          [e.node_id]: {
106	            node_id: e.node_id,
107	            state: "NORMAL",
108	            last_seen: e.ts,
109	            fw_version: "v1",
110	            label: e.node_id,
111	            blocked: 0,
112	          },
113	        };
114	      }
115	      break;
116	    case "NODE_DOWN":
117	      nodes = setNodeState(state, e.node_id, "OFFLINE");
118	      break;
119	    case "ANOMALY_DETECTED":
120	      nodes = setNodeState(state, e.node_id, "ALERT");
121	      counters.threats_detected += 1;
122	      activeNode = e.node_id;
123	      agent = { iterations: null, self_tpr: null, self_fpr: null };
124	      agentStatus = null;
125	      error = null;
126	      break;
127	    case "AGENT_STEP": {
128	      const text = String(e.payload.text ?? "");
129	      if (text.startsWith(PROGRESS_PREFIX)) {
130	        agentStatus = text; // live status — do not spam the timeline
131	        appendLine = false;
132	      } else if (text.toLowerCase().includes("unavailable")) {
133	        error = text; // agent unreachable — surface loudly
134	      }
135	      break;
136	    }
137	    case "FILTER_GENERATED":
138	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
139	      agent = {
140	        iterations: (e.payload.iterations as number) ?? null,
141	        self_tpr: (e.payload.self_tpr as number) ?? null,
142	        self_fpr: (e.payload.self_fpr as number) ?? null,
143	      };
144	      break;
145	    case "OTA_DEPLOYING":
146	      nodes = setNodeState(state, e.node_id, "UPDATING");
147	      break;
148	    case "DEPLOYED":
149	      nodes = setNodeState(state, e.node_id, "PROTECTED");
150	      counters.filters_deployed += 1;
151	      agentStatus = null; // done working
152	      break;
153	    case "FRAME_BLOCKED": {
154	      const c = Number(e.payload.count ?? 1);
155	      counters.frames_blocked += c;
156	      if (e.node_id && nodes[e.node_id]) {
157	        nodes = {
158	          ...nodes,
159	          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
160	        };
161	      }
162	      break;
163	    }
164	    case "LINK_VERDICT":
165	      if (e.payload.verdict === "malicious") counters.threats_detected += 1;
166	      break;
167	    default:
168	      break;
169	  }
170	
171	  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;
172	
173	  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
174	  let timeline = state.timeline;
175	  if (appendLine) {
176	    const { text, tone } = describe(e);
177	    const line: TimelineLine = { id: state.seq, ts: e.ts, node_id: e.node_id, type: e.type, text, tone };
178	    timeline = [line, ...state.timeline].slice(0, 60);
179	  }
180	
181	  return {
182	    ...state,
183	    nodes,
184	    counters,
185	    timeline,
186	    stage,
187	    activeNode,
188	    activeAttack,
189	    agent,
190	    agentStatus,
191	    error,
192	    seq: state.seq + 1,
193	  };
194	}
