94	function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
95	  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
96	  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
97	}
