99	export function reduce(state: DashState, msg: WsMessage): DashState {
100	  if (msg.type === "SNAPSHOT") {
101	    const nodes: DashState["nodes"] = {};
102	    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
103	    return { ...state, nodes, counters: msg.payload.counters };
104	  }
105	
106	  const e = msg;
107	  let nodes = state.nodes;
108	  const counters = { ...state.counters };
109	  let activeNode = state.activeNode;
110	  let activeAttack = state.activeAttack;
111	  let agent = state.agent;
112	  let agentStatus = state.agentStatus;
113	  let error = state.error;
114	  let incidents = state.incidents;
115	  let appendLine = true;
116	
117	  switch (e.type) {
118	    case "NODE_UP":
119	      if (e.node_id && !nodes[e.node_id]) {
120	        nodes = {
121	          ...nodes,
122	          [e.node_id]: {
123	            node_id: e.node_id,
124	            state: "NORMAL",
125	            last_seen: e.ts,
126	            fw_version: "v1",
127	            label: e.node_id,
128	            blocked: 0,
129	          },
130	        };
131	      }
132	      break;
133	    case "NODE_DOWN":
134	      nodes = setNodeState(state, e.node_id, "OFFLINE");
135	      break;
136	    case "ANOMALY_DETECTED":
137	      nodes = setNodeState(state, e.node_id, "ALERT");
138	      activeNode = e.node_id;
139	      agent = { iterations: null, self_tpr: null, self_fpr: null };
140	      agentStatus = null;
141	      error = null;
142	      break;
143	    case "AGENT_STEP": {
144	      const text = String(e.payload.text ?? "");
145	      if (text.startsWith(PROGRESS_PREFIX)) {
146	        agentStatus = text; // live status — do not spam the timeline
147	        appendLine = false;
148	      } else if (text.toLowerCase().includes("unavailable")) {
149	        error = text; // agent unreachable — surface loudly
150	      }
151	      break;
152	    }
153	    case "FILTER_GENERATED":
154	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
155	      agent = {
156	        iterations: (e.payload.iterations as number) ?? null,
157	        self_tpr: (e.payload.self_tpr as number) ?? null,
158	        self_fpr: (e.payload.self_fpr as number) ?? null,
159	      };
160	      break;
161	    case "OTA_DEPLOYING":
162	      nodes = setNodeState(state, e.node_id, "UPDATING");
163	      break;
164	    case "DEPLOYED":
165	      nodes = setNodeState(state, e.node_id, "PROTECTED");
166	      counters.filters_deployed += 1;
167	      agentStatus = null; // done working
168	      break;
169	    case "FRAME_BLOCKED": {
170	      const c = Number(e.payload.count ?? 1);
171	      counters.frames_blocked += c;
172	      if (e.node_id && nodes[e.node_id]) {
173	        nodes = {
174	          ...nodes,
175	          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
176	        };
177	      }
178	      break;
179	    }
180	    case "INCIDENT_CREATED":
181	      // Single source of truth for the threat counter across all domains.
182	      counters.threats_detected += 1;
183	      incidents = [e.payload as unknown as Incident, ...state.incidents].slice(0, 100);
184	      break;
185	    default:
186	      break;
187	  }
188	
189	  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;
190	
191	  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
192	  let timeline = state.timeline;
193	  if (appendLine) {
194	    const { text, tone } = describe(e);
195	    const incidentId = (e.payload.incident_id as string | undefined) ?? null;
196	    const line: TimelineLine = {
197	      id: state.seq,
198	      ts: e.ts,
199	      node_id: e.node_id,
200	      type: e.type,
201	      text,
202	      tone,
203	      incidentId,
204	    };
205	    timeline = [line, ...state.timeline].slice(0, 60);
206	  }
207	
208	  return {
209	    ...state,
210	    nodes,
211	    counters,
212	    timeline,
213	    stage,
214	    activeNode,
215	    activeAttack,
216	    agent,
217	    agentStatus,
218	    error,
219	    incidents,
220	    seq: state.seq + 1,
221	  };
222	}

